// Types for site/data/*.json (generated by scripts/export_site_data.py).
// Components only ever read these shapes; nothing is hardcoded.

/** A number traced to a CSV cell. `display` is the exact text to show. */
export interface SourcedNumber {
  label: string;
  value: number;
  display: string;
  unit: string;
  source: { file: string; column: string; where: Record<string, string> };
}

/** A whole number rounded from a sourced number (e.g. 2.15% -> 2 in 100). */
export interface DerivedNumber {
  label: string;
  value: number;
  display: string;
  unit: string;
  derived: { rule: string; from: SourcedNumber };
}

/** Text rendered from a template filled with sourced numbers. */
export interface RenderedText {
  text_template: string;
  numbers: Record<string, SourcedNumber | DerivedNumber>;
  text: string;
}

export interface Chart {
  id: string;
  title: string;
  type: string;
  x: string;
  y: string;
  /** A list value means "any of these" (rows keep the CSV order). */
  source: { file: string; columns: string[]; where: Record<string, string | string[]> };
  rows: Record<string, string | number | boolean | null>[];
}

export interface Finding {
  id: string;
  topic: string;
  headline: string;
  key_numbers: Record<string, SourcedNumber>;
  source: { file: string; queries: string[] }[];
  doesnt_show: string;
  recommendations: string[];
}

export interface TestDesignItem {
  label: string;
  text: string;
}

export interface Recommendation {
  id: string;
  title: string;
  findings: string[];
  target_metric: string;
  expected_direction: string;
  evidence: Record<string, SourcedNumber>;
  effort: string;
  details: {
    change: string;
    target_metric: string;
    expected_direction: string;
    test_design: TestDesignItem[];
    risk: string;
    effort: string;
  };
}

export interface Limitation {
  id: string;
  text: string;
}

export interface FindingsFile {
  findings: Finding[];
  recommendations: Recommendation[];
  limitations: Limitation[];
}

export interface KpisFile {
  window: { from: string; to: string; basis: string };
  kpis: Record<string, SourcedNumber>;
  metrics_tree: {
    formula: string;
    revenue: SourcedNumber;
    customers: SourcedNumber;
    orders: SourcedNumber;
    orders_per_customer: SourcedNumber;
    aov: SourcedNumber;
    note: string;
  };
}

export interface PipelineStep {
  step: number;
  label: string;
  row_count: number;
  rows_dropped: number | null;
  drop_reason: string | null;
}

export interface PipelinesFile {
  source: string;
  pipelines: Record<string, PipelineStep[]>;
  /** Checks that passed in the export, per finding. */
  checks: Record<string, RenderedText[]>;
}

export interface QueryEntry {
  finding: string;
  file: string;
  query: string;
  title: string;
  sql: string;
  annotations: { line_number: number; line: string; note: string }[];
  result: {
    file: string;
    columns: string[];
    rows: Record<string, string | number | boolean | null>[];
    total_rows: number;
  };
}

export interface QueriesFile {
  queries: QueryEntry[];
}

export interface ChapterCopy {
  id: string;
  title: string;
  cards: string[];
  /** Chart ids, in order (keys of charts.json items). */
  charts: string[];
  why: RenderedText;
  recommendation: string;
}

export type Level = "low" | "medium" | "high";

export interface SiteFile {
  meta: {
    title: string;
    nav_title: string;
    description: string;
    subtitle: RenderedText;
    og_image: string;
    og_image_alt: string;
  };
  hero: {
    eyebrow: string;
    kpis: { label: string; number: SourcedNumber }[];
    map_label: string;
    scroll_hint: string;
    how_to_read: string;
  };
  question: { label: string; title: string; body: RenderedText[]; tree_title: string };
  chapters: ChapterCopy[];
  recommendations: {
    label: string;
    title: string;
    intro: string;
    evidence_in: string;
    matrix: {
      title: string;
      x_label: string;
      y_label: string;
      impact_word: string;
      effort_word: string;
      note: string;
      /** Judgement per recommendation id (not data). */
      impact: Record<string, Level>;
      levels: Record<Level, string>;
      quadrants: Record<"quick_wins" | "big_bets" | "small_tweaks" | "deprioritise", string>;
    };
  };
  under_the_hood: {
    label: string;
    title: string;
    panels: { id: "model" | "quality" | "techniques"; title: string; text: string }[];
    model: Record<
      "raw_table" | "clean_view" | "foreign_key" | "built_from" | "used_by" | "rows" | "key_columns" | "joins" | "grain" | "hint" | "tables_heading" | "views_heading",
      string
    >;
    quality: { first: string[]; problem: string; decision: string; ref: string };
    techniques: { see_it_used: string; used_in: string; view_file: string; chapter: string };
  };
  limitations: { label: string; title: string };
  ui: Record<string, string>;
  links: {
    github: string;
    github_file_base: string;
    case_study_pdf: string;
    dataset: string;
    dataset_license: string;
    geo: string;
    author: string;
    /** Public URL of the deployed site; empty until deployment. */
    site: string;
  };
  footer: {
    dataset_credit: string;
    dataset_license: string;
    geo_credit: string;
    built_by: string;
    credits_label: string;
  };
  map: MapCopy;
}

/** Hero map text and sample figures (site.json "map"). */
export interface MapCopy {
  caption: RenderedText;
  phone_note: string;
  legend: { id: "on_time" | "late"; label: string; number: SourcedNumber }[];
  filter_label: string;
  filter_all: string;
  filter_late: string;
  zoom_in: string;
  zoom_out: string;
  controls_hint: string;
  tooltip: { delivered_orders: string; late_rate: string; median_days: string };
  poster_alt: string;
}

/** map.json: per-state delivery figures for the map tooltip. */
export interface MapMetaFile {
  source: string;
  states: Record<
    string,
    { delivered_orders: SourcedNumber; late_rate_pct: SourcedNumber; median_delivery_days: SourcedNumber }
  >;
}

/** map_arcs.json: the 3,000-order sample, one array per row in column order. */
export interface MapArcsFile {
  source: string;
  sample_rule: string;
  columns: string[];
  rows: (number | boolean | string)[][];
}

/** Plain-text labels; some charts group them (e.g. stage names). */
export type ChartLabels = Record<string, string | Record<string, string>>;

/** One chart's copy (charts.json items). */
export interface ChartCopy {
  id: string;
  finding: string;
  /** Id of the chart rows in findings.json, or null for a chart drawn from numbers. */
  data: string | null;
  title: RenderedText;
  subtitle: RenderedText;
  labels: ChartLabels;
  numbers: Record<string, SourcedNumber | DerivedNumber>;
}

/** charts.json: chart copy plus the chart rows of each finding. */
export interface ChartsFile {
  ui: Record<string, string>;
  delay_buckets: { promise: string; late: string[]; short: Record<string, string> };
  items: Record<string, ChartCopy>;
  source: string;
  /** Finding id -> its charts (rows copied from results/*.csv). */
  data: Record<string, Chart[]>;
}

/** schema.json: tables and views parsed from sql/00 and sql/03. */
export interface SchemaFile {
  source: string;
  tables: { name: string; kind: "table"; primary_key: string[]; row_count: number; columns: { name: string; type: string }[] }[];
  views: { name: string; kind: "view"; grain: string; row_count: number; built_from: string[] }[];
  relationships: { from: string; to: string; kind: "foreign key" | "built from" }[];
}

/** quality.json: data-quality issues and the decision taken for each. */
export interface QualityFile {
  source: string;
  issues: { id: string; issue: string; affected: number; unit: string; decision_ref: string; decision: string }[];
}

/** techniques.json: SQL techniques, the chapters whose View SQL shows them, and where they are used. */
export interface TechniquesFile {
  techniques: { technique: string; description: string; chapters: string[]; uses: { file: string; section: string }[] }[];
}
